<?php
if($path==='/api/customer/session'){respond(['customer'=>customerPublic(customer()),'csrf'=>$_SESSION['csrf']]);}
if($path==='/api/cart'){if($_SERVER['REQUEST_METHOD']==='GET')respond(['items'=>cartRows(),'csrf'=>$_SESSION['csrf']]);throttle('cart',60,600);$v=jsonInput();sessionOpen();if(($v['action']??'')==='remove'){unset($_SESSION['cart'][text($v['id']??'',50)]);respond(['ok'=>true,'count'=>count($_SESSION['cart']??[])]);}if(count($_SESSION['cart']??[])>=10)respond(['error'=>'Your cart can hold up to 10 experiences.'],422);$t=availableTour(text($v['tourId']??'',100));if(!$t||price($t)<=0)respond(['error'=>'This experience is not currently available for online booking.'],422);$date=validTourDate($v['date']??'');$q=bookingQuote($t,$v);$id=bin2hex(random_bytes(8));$_SESSION['cart'][$id]=['tourId'=>$t['id'],'date'=>$date,'adults'=>$q['adults'],'children'=>$q['children'],'units'=>$q['units'],'addons'=>is_array($v['addons']??null)?$v['addons']:[]];respond(['ok'=>true,'count'=>count($_SESSION['cart'])]);}
