if($path==='/api/customer/login'){throttle('customer-login',10,900);customerSchema();$v=jsonInput();$email=strtolower(trim((string)($v['email']??'')));$c=sql('SELECT * FROM customers WHERE email=?',[$email])->fetch(PDO::FETCH_ASSOC);$valid=password_verify((string)($v['password']??''),$c['hash']??'$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.');if(!$c||!$valid||accountDisabled($c['email']))respond(['error'=>'Email or password is incorrect.'],401);customerSignIn($c);respond(['ok'=>true,'csrf'=>$_SESSION['csrf']]);}
if($path==='/api/customer/logout'){sessionOpen();unset($_SESSION['customer'],$_SESSION['customerVersion'],$_SESSION['customerExpires']);session_regenerate_id(true);$_SESSION['csrf']=bin2hex(random_bytes(24));respond(['ok'=>true]);}
if($path==='/api/customer/bookings'){$c=customer();if(!$c)respond(['error'=>'Sign in to view your bookings.'],401);respond(['bookings'=>customerBookings($c['id'])]);}
if($path==='/api/customer/forgot'){throttle('customer-reset',5,3600);if(empty(smtpConfig()['password']))respond(['error'=>'Email recovery is not connected yet. Please contact our team for account assistance.'],503);customerSchema();$v=jsonInput();$c=sql('SELECT * FROM customers WHERE email=?',[strtolower(trim((string)($v['email']??'')))])->fetch(PDO::FETCH_ASSOC);if($c){$token=customerToken($c,'reset');notifyMail($c['email'],'Reset your Desert Sky password',"Use this link within one hour to reset your password:\n".ORIGIN.'/account/reset?token='.$token."\n\nIf you did not request this, ignore this email.");}respond(['ok'=>true,'message'=>'If an account uses this email, a recovery link will be sent.']);}
if($path==='/api/customer/reset'){throttle('customer-reset-submit',10,900);customerSchema();$v=jsonInput();$password=(string)($v['password']??'');if(strlen($password)<12||strlen($password)>200)respond(['error'=>'Use a password of 12–200 characters.'],422);$token=hash('sha256',(string)($v['token']??''));$db=database();$db->exec('BEGIN IMMEDIATE');$r=sql('SELECT customer FROM customer_tokens WHERE token=? AND purpose=? AND expires>?',[$token,'reset',time()])->fetchColumn();if(!$r){$db->exec('ROLLBACK');respond(['error'=>'This recovery link is invalid or expired.'],422);}sql('UPDATE customers SET hash=?,version=version+1 WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$r]);sql('DELETE FROM customer_tokens WHERE customer=? AND purpose=?',[$r,'reset']);$db->exec('COMMIT');respond(['ok'=>true]);}
